-- TRAIN WITH PANDA 0.9.5 · coach tools and education content.
-- Additive migration. Existing plans, articles, foods and customer assignments stay intact.
begin;
create or replace function panda_private.validate_effort_program(p jsonb)
returns void language plpgsql set search_path='' as $$
declare d jsonb; x jsonb; scale text; target numeric;
begin
 if jsonb_typeof(p->'sessions') is distinct from 'array' then raise exception 'Invalid training sessions'; end if;
 for d in select value from jsonb_array_elements(p->'sessions') loop
  if jsonb_typeof(d->'exercises') is distinct from 'array' then raise exception 'Invalid training exercises'; end if;
  for x in select value from jsonb_array_elements(d->'exercises') loop
   scale:=coalesce(x->>'effort_scale','');
   if scale='' then
    if x ? 'effort_target' and x->'effort_target' not in ('null'::jsonb,'""'::jsonb) then raise exception 'Select RIR or RPE for an effort target'; end if;
   else
    if scale not in ('RIR','RPE') or jsonb_typeof(x->'effort_target') is distinct from 'number' then raise exception 'Invalid effort scale or target'; end if;
    target:=(x->>'effort_target')::numeric;
    if target < (case when scale='RPE' then 1 else 0 end) or target>10 or target*2<>trunc(target*2) then raise exception 'Effort target must be 0–10 RIR or 1–10 RPE, in half-point steps'; end if;
   end if;
  end loop;
 end loop;
end $$;
create or replace function panda_private.validate_coaching_update()
returns trigger language plpgsql set search_path='' as $$
declare x jsonb; f text; ds text; start_date date; end_date date;
begin
 if new.kind='programs' then perform panda_private.validate_effort_program(new.data);
 elsif new.kind='plan_history' and new.data->>'type'='programs' then
  if jsonb_typeof(new.data->'versions') is distinct from 'array' then raise exception 'Invalid plan history'; end if;
  for x in select value from jsonb_array_elements(new.data->'versions') loop perform panda_private.validate_effort_program(x->'snapshot');end loop;
 elsif new.kind='supplements' then
  if jsonb_typeof(new.data->'items') is distinct from 'array' or jsonb_array_length(new.data->'items')>40 then raise exception 'Use up to 40 supplement entries';end if;
  for x in select value from jsonb_array_elements(new.data->'items') loop
   if jsonb_typeof(x) is distinct from 'object' or coalesce(length(trim(x->>'name')),0)=0 then raise exception 'Give every supplement a name';end if;
   foreach f in array array['name','dose','timing','purpose','notes'] loop
    if x ? f and (jsonb_typeof(x->f) is distinct from 'string' or length(x->>f)>3000) then raise exception 'Invalid supplement text';end if;
   end loop;
   if x ? 'status' and (jsonb_typeof(x->'status') is distinct from 'string' or x->>'status' not in ('active','paused')) then raise exception 'Invalid supplement status';end if;
   start_date:=null;end_date:=null;
   foreach f in array array['start_date','end_date'] loop
    ds:=x->>f;
    if x ? f and jsonb_typeof(x->f) is distinct from 'string' then raise exception 'Invalid supplement date';end if;
    if coalesce(ds,'')<>'' then
     if ds !~ '^\d{4}-\d{2}-\d{2}$' or to_char(ds::date,'YYYY-MM-DD')<>ds then raise exception 'Invalid supplement date';end if;
     if f='start_date' then start_date:=ds::date;else end_date:=ds::date;end if;
    end if;
   end loop;
   if start_date>end_date then raise exception 'The end date must follow the start date';end if;
  end loop;
 elsif new.kind='clients' and new.data ? 'cardio_guidance' then
  if jsonb_typeof(new.data->'cardio_guidance') is distinct from 'string' or length(new.data->>'cardio_guidance')>3000 then raise exception 'Invalid cardio guidance';end if;
 elsif new.kind='foods' and new.data ? 'fiber' and new.data->'fiber'<>'null'::jsonb then
  if not panda_private.valid_number(new.data->'fiber',0,1000) then raise exception 'Fiber must be a non-negative number or unknown';end if;
 end if;
 return new;
end $$;
revoke all on function panda_private.validate_effort_program(jsonb),panda_private.validate_coaching_update() from public,anon,authenticated;
drop trigger if exists panda_coaching_update on public.panda_records;
create trigger panda_coaching_update before insert or update on public.panda_records for each row execute function panda_private.validate_coaching_update();
insert into public.panda_records(kind,id,data) select 'articles', value->>'id',value from jsonb_array_elements($panda095$[{"id":"hub-nutrition","category":"Nutrition Fundamentals","title":"Nutrition Fundamentals","summary":"Understand energy, nutrients and portions, then turn the numbers in your plan into meals you can repeat.","sections":[["Calories & energy balance","Calories describe energy. Over time, eating less energy than you use tends to reduce body weight; eating more tends to increase it. Daily readings are noisy, so one weigh-in cannot tell you whether a plan is working.\n\nUse the coach’s target as a starting point. Compare several weeks of intake, activity, hunger and measurements before changing it. A calculator estimates requirements; it does not measure your metabolism."],["Protein, carbs & fats","Protein supports the maintenance and repair of body tissues. Carbohydrate supplies energy for daily activity and training. Fat contributes to essential functions and makes meals satisfying. All three belong in the conversation; no single macro makes the whole diet good or bad.\n\nIn the app, targets and planned meal totals are separate. If they differ, ask whether the portion or the target should change instead of silently adding food."],["Fiber & micronutrients","Fiber comes from plant foods; vitamins and minerals support many normal body functions. The WHO advises at least 25 g of naturally occurring fiber daily for people older than ten. Individual needs and tolerance vary, so follow your assigned target and increase gradually.\n\nTry a practical food change, such as adding beans or replacing a refined grain with a whole grain. Unknown fiber values in the app mean the value needs checking, not that the food contains none."],["Portion control","A food entry is only useful if the portion unit matches what you eat. One scoop, one pack and 100 g are different references. Rice weighed dry is different from rice weighed cooked because the water content changes.\n\nFor a recipe, check how many servings the whole batch makes. Divide the finished dish into that number of portions, or adjust the servings in your assigned plan with your coach."],["Meal timing","Choose a meal pattern that fits your work, appetite and training. An elaborate schedule that you cannot maintain is less useful than a repeatable one. Before training, allow time to digest a meal you tolerate; very large meals immediately beforehand may feel uncomfortable.\n\nAfter training, return to your normal eating plan. You do not need to panic about missing a very narrow post-workout window. Discuss individual timing needs with your coach."],["Calorie deficit vs surplus","A deficit means less energy than estimated maintenance; a surplus means more. The size and duration should suit the goal, recovery and the person. Maintenance is also a valid phase, especially when building routines or managing a demanding schedule.\n\nDo not interpret a lower target as automatically better. Persistent exhaustion, poor training, dizziness or a difficult relationship with food are reasons to discuss the plan and seek appropriate support."],["How to read food labels","Start with the serving size and the number of servings in the package. Then compare energy, protein, carbohydrate, fat and fiber using the same reference amount. Front-of-pack words such as “protein” do not tell you the complete nutritional profile.\n\nLabels differ between countries in how carbohydrate and fiber are reported. Keep the label’s reference basis consistent when entering a food, and retain a note if the values are estimates."],["How to track calories and macros","Record the food, amount and preparation state. Include cooking oils, dressings and drinks when relevant. Use the same reliable entry repeatedly instead of selecting whichever result makes the numbers look best.\n\nTracking is a feedback tool, not a test of character. If precision creates anxiety, tell your coach and agree on a simpler method. Your next action: check the portion units in one full day of your assigned plan."]],"image":"assets/recipes/09.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"WHO · Healthy diet","url":"https://www.who.int/news-room/fact-sheets/detail/healthy-diet"},{"title":"ISSN · Protein and exercise","url":"https://link.springer.com/article/10.1186/s12970-017-0177-8"},{"title":"Mifflin et al. · Resting energy equation","url":"https://pubmed.ncbi.nlm.nih.gov/2305711/"}],"hub":"nutrition","icon":"nutrition"},{"id":"hub-swaps","category":"Food Swap Guide","title":"Food Swap Guide","summary":"Keep your plan flexible by understanding what a substitution matches—and what it changes.","sections":[["Protein swaps","Choose the nutrient you want to match before choosing the replacement. Chicken, fish, eggs, yogurt and tofu can contribute protein, but their fat, energy and serving sizes differ.\n\nFor example, a replacement with 20 g protein per 100 g needs 150 g to supply 30 g protein. That calculation matches protein only. Compare the rest of the meal before confirming the swap with your coach."],["Carb swaps","Rice, potatoes, pasta, bread and fruit can all contribute carbohydrate. Match the preparation state first: cooked rice cannot be compared gram-for-gram with dry pasta.\n\nIf your planned portion provides 40 g carbohydrate and the replacement provides 25 g per 100 g, the equivalent is 160 g. Then check fiber, energy and the practical portion. Use the app’s food details to confirm the numbers."],["Healthy fat swaps","Nuts, seeds, avocado and olive oil can fit into meals, but they are not interchangeable spoon-for-spoon. Nuts also contain protein and fiber; oil does not provide the same food structure.\n\nMeasure the portion you actually use. A free-poured dressing can differ considerably from a measured amount. Select the replacement because it fits the dish and your preferences, then adjust the quantity with your coach."],["Low-calorie alternatives","A useful alternative keeps the meal enjoyable while changing a part that contributes substantial energy. Examples include asking for dressing separately, using a smaller amount of oil, or replacing a sugary drink with water.\n\n“Low calorie” does not automatically mean more nutritious or more satisfying. Keep the main meal adequate. Avoid replacing meals with products simply because the label shows a small number."],["Vegetarian options","Consider tofu, tempeh, beans, lentils, dairy or eggs according to your preferences. Legumes usually contribute both carbohydrate and protein, so replacing meat with beans may also change the carbohydrate total.\n\nBuild a whole meal rather than trying to force every plant food into the same portion as meat. Tell your coach whether you avoid all animal products or only particular foods so the plan can be appropriate."],["The same macros with different foods","Matching three macro totals still does not match fiber, micronutrients, allergens, preparation time or fullness. Two meals can fit similar numbers while feeling very different.\n\nUse this order: identify the goal of the swap, check the label and unit, calculate the portion, compare the full meal, then save the agreed version. Your next action: agree on two reliable alternatives for the meal you most often miss."]],"image":"assets/recipes/18.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"swaps","icon":"nutrition"},{"id":"hub-eating-out","category":"Eating Out Guide","title":"Eating Out Guide","summary":"Make restaurant and social meals manageable without turning one imperfect meal into an abandoned week.","sections":[["Restaurant ordering","Read the menu before arriving when practical. Choose a main dish you enjoy, identify a protein source and consider a vegetable or other side that fits your plan. Ask about preparation if sauces, allergies or ingredients matter.\n\nRestaurant portions and oil use vary. An estimate is more honest than a false exact number. Share recurring restaurant meals with your coach so you can agree on a repeatable approach."],["Fast-food choices","Look for published nutrition information when available and check whether it describes the item alone or a full meal. Choose the portion deliberately; extras such as drinks, sauces and sides may change the total substantially.\n\nThere is no universal best order. Your budget, preferences and available options matter. Pick a workable meal and continue with your normal routine afterwards."],["Social meals","Decide what matters before the event: enjoying the food, seeing friends, or keeping a particular routine. You can do more than one without tracking every bite. Consider a normal meal earlier in the day rather than arriving extremely hungry.\n\nYou do not owe anyone an explanation for your choices. If asked, a simple “this works for me” is enough. Let your coach know about regular events."],["Buffets","Look at the options before filling your plate. Start with a meal-sized portion and sit down to eat it. You can return if you are still hungry; there is no need to sample everything at once.\n\nChoose favourites intentionally rather than collecting foods because they are available. If you track, describe the plate approximately. Do not invent precise gram amounts after the fact."],["Business dinners","Plan for uncertainty: timings may change, menus may be fixed, and the meal may last longer than expected. Bring a practical snack if the gap between meals will be large.\n\nAt dinner, make the choices available to you and focus on the conversation. A predictable breakfast and lunch can make the day easier without compensatory restriction. Record context for the weekly check-in if the schedule repeatedly disrupts your plan."],["When you cannot follow the diet","Return to your usual plan at the next suitable meal. Avoid punishment workouts, fasting to “erase” food or treating the week as ruined. One meal is a small part of a longer pattern.\n\nTell your coach what happened: availability, hunger, travel, cost or preference. That information improves the plan. Your next action: choose a simple fallback meal for days when the planned option is unavailable."]],"image":"assets/recipes/27.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"eating-out","icon":"nutrition"},{"id":"hub-shopping","category":"Grocery Shopping Guide","title":"Grocery Shopping Guide","summary":"Turn your assigned meals into a practical shopping list that fits your budget, kitchen and week.","sections":[["Protein shopping list","Start from the meals you will actually prepare. Depending on your preferences, options may include poultry, fish, eggs, yogurt, cottage cheese, tofu and pulses. Choose quantities for the number of planned servings.\n\nCheck storage life and freezer space. Buying a large pack is only economical if you can use it safely. Keep one convenient backup, such as an appropriate canned or frozen option."],["Carb shopping list","List the grains, bread, potatoes and fruit used in your plan. Check whether the recipe quantity is dry, cooked or drained before converting it into packs to buy.\n\nAvoid buying a different preparation simply because the package looks similar. Microwave rice, dry rice and a prepared rice dish may use different portion references. Save the product label if your coach needs to update the food entry."],["Healthy fats","Buy the portions you can use: nuts, seeds, olive oil and avocado are examples. A small bottle or pack may be more practical than a bulk purchase that goes unused.\n\nInclude cooking fats and dressings in the list. Measuring a portion once helps you understand the amount you usually use. It is an awareness exercise, not a requirement to make every meal laboratory precise."],["Fruits & vegetables","Choose a variety you enjoy and can realistically prepare. Fresh, frozen and suitable canned foods can all make the week easier. Separate produce for immediate meals from items that keep longer.\n\nA useful pattern is one ready-to-eat option, one frozen option and vegetables for your main recipes. Wash and prepare according to the food and store appropriately. Variety matters more than chasing one “superfood”."],["Meal-prep essentials","Before shopping, check containers, a kitchen scale if you use one, freezer bags and basic cooking equipment. Pick a preparation session that fits your calendar. You do not have to cook the entire week at once.\n\nLabel stored food with the preparation date and follow appropriate refrigeration, reheating and food-safety guidance. If storage conditions are uncertain, prepare a smaller batch."],["Budget-friendly foods","Compare unit prices and usable portions, not just the price on the front. Seasonal produce, frozen vegetables, oats and pulses can be practical options, depending on local prices.\n\nBuild the list from the app’s grocery view, check the cupboard first, and remove duplicates. Your next action: choose two main meals that share ingredients so your shopping produces fewer leftovers."]],"image":"assets/recipes/04.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"shopping","icon":"nutrition"},{"id":"hub-fat-loss","category":"Fat Loss Academy","title":"Fat Loss Academy","summary":"Understand trends, plateaus and maintenance so fat loss is guided by evidence rather than daily reactions.","sections":[["How fat loss actually works","A sustained energy deficit is the underlying driver of fat loss. Training, daily activity, food choices and routines influence whether that deficit is manageable. A single food, supplement or workout does not bypass the overall pattern.\n\nUse strength training and adequate nutrition as part of the plan, then review energy, hunger and performance alongside measurements. The aim is an approach you can carry out, not the largest possible deficit."],["Belly fat & spot reduction","You cannot reliably choose where fat is lost by training that body part. Abdominal exercises can develop the muscles and improve skill, but they do not selectively remove the fat covering them.\n\nAvoid judging progress by one area alone. Compare trends in body weight, measurements, photos and how clothing fits. Genetics and individual fat distribution affect which changes become visible first."],["How fast should weight change?","An appropriate rate depends on starting body size, health, training, previous dieting and the goal. There is no single weekly number that is right for everyone. Faster loss can make recovery and adequate eating harder.\n\nAgree on a range with your coach and review several weeks. If the process brings persistent dizziness, marked fatigue, menstrual changes or distress around food, pause and seek qualified assessment."],["Weight-loss plateaus","A plateau should be judged over a meaningful trend, not a few unchanged mornings. Check measurement consistency, meal portions, activity and adherence before assuming the body has stopped responding.\n\nBring a clear record to your coach: dates, average intake if tracked, steps and relevant changes. Adjust one factor at a time so you can learn what helped. Do not repeatedly cut food based on frustration."],["Why scale weight changes","Water, stored carbohydrate, food in the digestive system, sodium, menstrual changes and the timing of a weigh-in can move body weight without equivalent fat change. A salty meal can therefore affect the next morning’s reading.\n\nMeasure under similar conditions if weighing is useful for you. Treat the individual point as context and the longer pattern as the signal. The app preserves dated readings so you can compare fairly."],["Refeeds and diet breaks","A refeed or diet break is a planned period with changed intake, often closer to maintenance. It may make a long diet easier to manage, but it is not a guaranteed “metabolic reset” or a licence for uncontrolled eating.\n\nAgree on the purpose, duration and next review with your coach. Keep the same basic meal structure and use the break to observe recovery and hunger."],["Maintaining after fat loss","Maintenance needs a plan too. Discuss how intake, activity and monitoring will change after the deficit. Expect ordinary fluctuations rather than demanding that body weight remain on one exact number.\n\nKeep the routines that were useful: regular meals, strength training, practical shopping and honest check-ins. Your next action: agree on the signs that would trigger a review, rather than reacting to every small increase."]],"image":"assets/editorial/covers/progressive-overload.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"fat-loss","icon":"flame"},{"id":"hub-muscle","category":"Muscle Building Academy","title":"Muscle Building Academy","summary":"Build a training process you can recover from, repeat and progressively improve.","sections":[["Progressive overload","Progressive overload means increasing the training challenge as capacity develops. It may involve more load, repetitions or appropriately planned work. Better control and a more consistent range of motion also improve the quality of comparison.\n\nUse the same exercise setup and follow the coach’s progression rule. Adding weight while shortening the movement changes the task and can make the training log misleading."],["Training volume","Volume describes how much training you perform. In practical coaching, challenging sets for a muscle group are one useful reference, but the quality of the sets and your recovery matter too.\n\nMore is not automatically better. If later sets lose the intended technique or interfere with the next session, discuss the workload. Record what you actually completed instead of copying the planned amount."],["Training frequency","Frequency is how often you train a movement or muscle group. Different schedules can work when the total work, exercise choice and recovery fit the person. Choose days you can attend consistently.\n\nIf work changes, ask your coach how to distribute the sessions. Do not squeeze every missed workout into consecutive days without considering fatigue and the next week’s plan."],["Exercise selection","Choose exercises that suit your equipment, goals, experience and movement tolerance. A familiar machine can be more useful than a complex lift you cannot set up reliably.\n\nUse the exercise library to confirm the intended variation, then keep it stable long enough to learn it. Report discomfort and equipment restrictions. A substitution should have a clear purpose rather than simply look more advanced."],["Muscle recovery","Training provides a stimulus; adaptation also requires recovery. Sleep, adequate food, sensible scheduling and the amount of other stress all affect how ready you feel. Soreness alone is not a score for workout quality.\n\nCompare performance, sleep and motivation across several sessions. Persistent decline is useful feedback for your coach. One tired day may call for an adjustment rather than abandoning the programme."],["Bulking vs lean gaining","A larger energy surplus does not guarantee a proportionally larger muscle gain. “Lean gaining” usually describes a more restrained approach with closer monitoring of weight, measurements and training.\n\nSelect an intake strategy with your coach. Review the direction of change alongside strength and recovery, then adjust gradually. The labels matter less than what the plan actually asks you to do each day."],["Natural muscle-building expectations","Muscle growth is gradual and varies with training experience, genetics, age, nutrition and consistency. Progress may be faster early in training and slower as experience increases. Social media images cannot establish what is realistic for your body.\n\nUse months of comparable records, not a single transformation photo. Your next action: choose one exercise and one routine you can improve consistently during the next training block."]],"image":"assets/editorial/covers/strength-foundation.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"muscle","icon":"workouts"},{"id":"hub-training","category":"Training Education","title":"Training Education","summary":"Decode the instructions in your workout: effort, repetitions, tempo, recovery and advanced methods.","sections":[["Warm-up & activation","Prepare for the specific session. Start with movement that raises your readiness, then use lighter practice sets of the first demanding exercises. An activation drill should help you perform the main work, not leave you exhausted before it.\n\nAsk your coach which warm-up sets are separate from working sets. Increase load gradually and use the warm-up to check equipment, range and how the movement feels today."],["Sets & reps","A repetition is one complete execution of the movement; a set is a group of repetitions before a rest. Three sets of 8–12 means a prescribed range for each working set, not 24–36 repetitions performed without a break.\n\nKeep the intended technique throughout. If the range is repeatedly too easy or impossible at the prescribed effort, report the actual load and repetitions to your coach."],["RPE & RIR","RIR means repetitions in reserve: the clean repetitions you estimate you could still complete at the end of a set. RPE means rating of perceived exertion. For resistance training, this app uses the RIR-based 1–10 RPE convention, not Borg’s 6–20 scale.\n\nNear the hard end, RPE 10 is approximately 0 RIR, RPE 9 about 1 RIR, RPE 8 about 2 RIR and RPE 7 about 3 RIR. These are estimates. Do not count repetitions that would require losing the agreed technique."],["Rest periods","Rest allows you to prepare for the next set. The assigned duration helps standardise the session and may differ between demanding lifts and smaller exercises.\n\nUse a timer when helpful, but also check that you are ready and the equipment is safe. If a short rest makes the prescribed work impossible, tell your coach. Shortening rest is not automatically an improvement."],["Tempo","Tempo describes the pace of parts of a repetition. Coaches may use words or a sequence of numbers for lowering, pauses and lifting. Ask which order your coach uses before interpreting a four-number prescription.\n\nUse the cue to control the movement rather than rush to finish the set. A slower tempo changes the task, so do not compare it directly with a faster version without noting the difference."],["Supersets","A superset pairs exercises with little or no rest between them, followed by the agreed recovery. It can help organise time, but the pairing influences fatigue and performance.\n\nCheck the exact order, whether the exercises use the same muscle groups, and where the rest belongs. Busy equipment may make a superset impractical; agree on a fallback rather than occupying several stations indefinitely."],["Dropsets","A dropset continues an exercise after reducing the load. It is an optional way to organise demanding work, not a requirement for progress.\n\nFollow the coach’s limits for the number of reductions and the stopping point. Do not add dropsets to every exercise because the session felt short. Extra fatigue may affect the rest of the programme."],["Training to failure","Failure is task-specific: you cannot complete another repetition under the agreed conditions. Technical breakdown and pain are reasons to stop; they are not targets to push through.\n\nTraining to failure is not necessary on every set. The choice depends on the exercise, safety setup, experience and programme. Use spotters or safety supports where appropriate and follow the assigned RIR or RPE."],["Deloads","A deload is a planned reduction in training stress, usually by adjusting load, volume or effort. It creates space to recover while maintaining useful practice.\n\nA deload does not mean you have failed or lost your progress. Confirm which variables change and when the normal plan resumes. Avoid adding unplanned extra work to compensate for the lighter schedule."],["Proper exercise technique","Use the library to understand the setup, movement and coaching cues, then apply the variation assigned to you. A photograph is a reference, not a personalised assessment of your technique.\n\nIf you are uncertain, ask for a coach review and describe what feels unclear. Your next action: identify the effort target and one technique cue before beginning your next working set."]],"image":"assets/editorial/covers/hit-hiit.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"Helms et al. · Repetitions in reserve and RPE","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4961270/"}],"hub":"training","icon":"workouts"},{"id":"hub-cardio","category":"Cardio & Conditioning","title":"Cardio & Conditioning","summary":"Use cardio and everyday movement to support fitness while keeping the whole training week manageable.","sections":[["Zone 2 cardio","“Zone 2” can mean different things in different heart-rate models. Do not assume that every watch or gym machine uses the same boundaries. Your coach should define the intended effort.\n\nFor a practical easy-to-moderate session, breathing is elevated but a conversation is still possible. Heat, fatigue and medication can affect heart rate. Use the agreed duration and effort rather than chasing a generic number."],["HIIT","High-intensity interval training alternates harder bouts with recovery. It differs from HIT strength-training approaches. The work duration, recovery and number of rounds determine the session, not simply feeling exhausted.\n\nHIIT is optional and should fit your experience and recovery. Start with the assigned format. Do not replace every easy cardio session with intervals just because the interval session is shorter."],["Steps & daily activity","Walking, household tasks and movement during work contribute to daily activity. Step counts can make a routine visible, but they are estimates and depend on the device.\n\nSet a realistic baseline before increasing a target. A short walk after a regular daily event can be easier to maintain than one large walk at an unpredictable time. Compare your own pattern using the same device."],["Cardio for fat loss","Cardio can contribute to energy expenditure and fitness, but exercise-machine calorie readings are estimates. Avoid automatically eating back every displayed calorie or using exercise as punishment for food.\n\nKeep the dietary plan and the activity plan coordinated with your coach. If extra cardio leaves you exhausted and less active for the rest of the day, the overall plan may need to change."],["Cardio vs resistance training","The two support different, overlapping aspects of fitness. Resistance training develops strength and muscle; aerobic activity develops cardiorespiratory capacity. Public-health guidance includes both aerobic and muscle-strengthening activity.\n\nThe balance should reflect your goal and schedule. If strength performance is a priority, discuss how demanding cardio sessions are placed around lower-body training."],["Increasing conditioning","Change one part of the plan at a time: duration, frequency or effort. A repeatable progression gives you better feedback than increasing all three simultaneously.\n\nRecord the activity type and how it felt, not only minutes. Walking uphill for twenty minutes and an easy cycle for twenty minutes are different sessions. Review recovery before making the next increase."],["Recovery between sessions","Plan easy days and recovery around harder work. Persistent breathlessness out of proportion to the activity, chest pain or faintness require stopping and appropriate medical assessment.\n\nFor ordinary fatigue, discuss a shorter or easier alternative with your coach. Your next action: check the activity target in your profile and agree on the effort and schedule that make those minutes meaningful."]],"image":"assets/editorial/covers/progressive-overload.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"WHO · Physical activity","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity"}],"hub":"cardio","icon":"energy"},{"id":"hub-recovery","category":"Recovery & Lifestyle","title":"Recovery & Lifestyle","summary":"Recognise when to push, when to adjust and which everyday routines support your training.","sections":[["Sleep fundamentals","Treat sleep as part of the schedule. A reasonably consistent bedtime and wake time, a comfortable room and a wind-down routine can make it easier to settle. Adults generally need at least seven hours, with age and individual needs affecting the appropriate range.\n\nLook at repeated patterns rather than grading a single night. If sleep difficulties persist or you experience concerning daytime sleepiness, seek appropriate advice instead of relying on a supplement stack."],["Stress management","Work, family and training all place demands on your time and attention. Stress is not something you must eliminate before making progress. The aim is to keep the plan workable during demanding periods.\n\nChoose one small action: prepare tomorrow’s meal, take a short break or reduce a nonessential task. Describe major changes in your check-in so the coach can adjust expectations."],["Rest days","A rest day is part of the programme. It may include comfortable everyday movement, but it does not need an extra workout to “count”.\n\nUse the day for the practical things that support the next session: food preparation, equipment, sleep and scheduling. If you enjoy a walk, keep it appropriate to the recovery goal rather than turning every rest day into a competition."],["Hydration","Follow your assigned fluid guidance and discuss changes for heat, long sessions or heavy sweating. Requirements vary with conditions and the person; forcing large volumes is not automatically healthier.\n\nKeep fluid available and use your daily record to notice missed opportunities. If a clinician has advised fluid restriction or electrolyte management, that advice takes priority over a generic fitness target."],["Recovery signs","Useful signals include stable performance, manageable soreness, normal appetite and a routine you can maintain. No single wearable score or body sensation tells the whole story.\n\nCompare several signals over time. If performance and sleep are declining together, bring that pattern to your coach. A clear description of the change is more useful than simply marking yourself “unmotivated”."],["Managing fatigue","Separate expected tiredness after work from a pattern that persists or worsens. Consider recent changes in training, food, sleep and other demands.\n\nAvoid adding stimulants to conceal every sign of fatigue. Agree on a reduced session or recovery day when appropriate. New or unexplained symptoms deserve healthcare advice rather than a routine coaching adjustment."],["Training when tired","Use the warm-up to assess readiness. If the movement feels safe but the normal load is unusually difficult, the coach may have an option to reduce load, sets or effort.\n\nDo not chase a personal record to prove commitment. Your next action: agree on a minimum session and a clear stop rule before the next difficult week arrives."]],"image":"assets/education/education-recovery.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"CDC · About sleep","url":"https://www.cdc.gov/sleep/about/index.html"}],"hub":"recovery","icon":"moon"},{"id":"hub-supplements","category":"Supplements HQ","title":"Supplements HQ","summary":"Understand optional supplements, recognise weak claims and use only the plan that has been reviewed for you.","sections":[["Which supplements are useful?","Start with a specific need. A supplement may fill a dietary gap or support a particular performance goal, but it does not replace training, food or sleep. More ingredients do not automatically produce a better result.\n\nYour coach’s assigned plan should identify the product, amount, timing and reason. A reference entry is educational; it is not an instruction for every client to take that product."],["Creatine","Creatine monohydrate can support repeated high-intensity efforts. It is optional, and an initial increase in scale weight may reflect water retention rather than fat gain.\n\nUse the amount agreed for your situation. Tell your healthcare professional about supplements if you have a medical condition, take medication or are being investigated for symptoms. Do not interpret a training guide as individual medical clearance."],["Protein powder","Protein powder is a convenient food supplement when ordinary meals make your protein target difficult to reach. It is not essential, and whey isolate is not automatically necessary for everyone.\n\nCheck the label, allergens, serving size and your tolerance. Count its nutrients in your meal plan. Taking extra protein on top of an already adequate intake does not guarantee extra muscle growth."],["Omega-3","Fish and other dietary sources can contribute omega-3 fats. A supplement decision should consider your diet and health context; it is not a universal recovery prescription.\n\nCheck EPA and DHA amounts rather than confusing total fish-oil weight with active fatty-acid content. Discuss use with a clinician or pharmacist if you take medication, especially medicines affecting blood clotting."],["Vitamin D","Vitamin D supports bone health and other normal functions. Supplementation should reflect diet, exposure, local guidance and, where appropriate, clinical assessment. It is not a guaranteed testosterone booster.\n\nK2 is not automatically mandatory whenever vitamin D is used. Avoid combining several products without checking their total vitamin content. Ask a qualified professional before using high-dose preparations."],["Multivitamins and ZMA","A multivitamin can help address specific intake gaps but cannot make a restrictive, poorly balanced diet complete. ZMA is a combination of minerals and vitamin B6; it should not be presented as a guaranteed sleep or hormone solution.\n\nCheck duplication with other products. “More than the daily requirement” is not necessarily a benefit. Address the dietary or sleep issue itself with suitable support."],["Caffeine and pre-workout","Caffeine can improve performance in some settings, but it can also disturb sleep or cause unpleasant effects. Natural and synthetic caffeine contain the same active molecule; “natural” does not guarantee a jitter-free experience.\n\nCount caffeine from coffee, energy drinks and supplements together. Avoid unmeasured pure caffeine and unclear blends. Dose and timing should reflect tolerance and health circumstances, not a stronger-is-better approach."],["When supplements are unnecessary","A product without a clear purpose adds expense and complexity. Amino-acid products may be unnecessary when protein intake is already adequate; many products marketed for fat burning or hormone optimisation make claims beyond their evidence.\n\nBefore adding something, ask: what problem does this solve, how will we judge its value, and what would make us stop? A simple plan is easier to follow and review."],["Supplement safety","Check the ingredient list, exact amounts, product quality and possible interactions. Independent batch testing can reduce some contamination risk but cannot guarantee that every product is appropriate or permitted in your sport.\n\nYohimbe/yohimbine can cause serious adverse effects and is not included as a routine fat-loss recommendation here. Ashwagandha also has important cautions, including reported liver injury and pregnancy concerns. Seek qualified advice before use; stop and obtain help if concerning symptoms occur."]],"image":"assets/education/education-recovery.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[{"title":"NIH ODS · Exercise and athletic performance","url":"https://ods.od.nih.gov/factsheets/ExerciseAndAthleticPerformance-HealthProfessional/"},{"title":"NIH ODS · Omega-3","url":"https://ods.od.nih.gov/factsheets/Omega3FattyAcids-Consumer/"},{"title":"NIH ODS · Vitamin D","url":"https://ods.od.nih.gov/factsheets/VitaminD-Consumer/"},{"title":"NCCIH · Yohimbe","url":"https://www.nccih.nih.gov/health/yohimbe"},{"title":"NCCIH · Ashwagandha","url":"https://www.nccih.nih.gov/health/ashwagandha"},{"title":"ISSN · Creatine","url":"https://link.springer.com/article/10.1186/s12970-017-0173-z"},{"title":"ISSN · Protein and exercise","url":"https://link.springer.com/article/10.1186/s12970-017-0177-8"},{"title":"FDA · Caffeine","url":"https://www.fda.gov/consumers/consumer-updates/spilling-beans-how-much-caffeine-too-much"},{"title":"NIH · Vitamin K","url":"https://ods.od.nih.gov/factsheets/VitaminK-Consumer/"},{"title":"NIH · Weight-loss supplements","url":"https://ods.od.nih.gov/factsheets/WeightLoss-Consumer/"},{"title":"NCCIH · Berberine","url":"https://www.nccih.nih.gov/health/berberine-and-weight-loss-what-you-need-to-know"}],"hub":"supplements","icon":"water"},{"id":"hub-mindset","category":"Mindset & Consistency","title":"Mindset & Consistency","summary":"Build a routine that survives real life, missed sessions and ordinary changes in motivation.","sections":[["Consistency over perfection","Consistency is the pattern you return to, not an unbroken run of perfect days. A plan should have enough structure to guide you and enough flexibility to survive an unexpected day.\n\nMeasure success with actions you can repeat: preparing a meal, attending a session or sending an honest check-in. Do not let a missed target erase the useful work already completed."],["Motivation vs discipline","Motivation changes. A routine reduces how many decisions you need to make when motivation is low. Discipline can mean adjusting intelligently, not forcing the hardest option every time.\n\nPut the session in your calendar, prepare the equipment and agree on a smaller alternative. The easier it is to start, the less you need to rely on a particular mood."],["Building habits","Choose a small action, a reliable cue and a realistic setting. For example: after finishing work, put training clothes on before checking messages. Make the action specific enough that you know whether you did it.\n\nKeep the first version manageable. Review what interrupted it and change the environment or timing. Add complexity only when the basic routine is working."],["Handling missed workouts","Ask where the missed session fits in the remaining week. Sometimes moving it works; sometimes skipping it and continuing is more practical. Avoid doubling the workload without considering recovery.\n\nTell your coach whether the problem was time, access, fatigue or uncertainty. A repeated obstacle is a design problem in the routine, not evidence that you lack commitment."],["Handling “cheat meals”","Food does not need a moral label. A meal outside the plan is an event to understand, not a reason for punishment or a total restart.\n\nReturn to your normal routine and note the context if it is useful. If the plan repeatedly leads to feeling deprived or out of control, discuss that openly and seek qualified support where needed."],["Consistency while travelling","Choose a small set of anchors: a workable breakfast, daily movement and a realistic sleep opportunity. The travel version of your routine may be different from the home version.\n\nAsk for an equipment-limited workout in advance. Pack only what helps you follow the plan. A shorter, repeatable approach can preserve continuity without taking over the trip."],["Dealing with slow progress","Separate the outcome from the actions that influence it. Check whether the planned actions are happening and whether the measurements are comparable before deciding the plan has failed.\n\nUse a review date instead of evaluating yourself after every session. Your next action: choose one repeatable behaviour for the coming week and tell your coach how you will make it easier."]],"image":"assets/editorial/covers/checkin.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"mindset","icon":"target"},{"id":"hub-tracking","category":"Progress Tracking","title":"Progress Tracking","summary":"Collect comparable records and use them to make better coaching decisions.","sections":[["How to weigh yourself","If weighing is appropriate for you, use the same scale on a firm surface and similar conditions, such as after using the bathroom and before breakfast. Record the date and avoid switching methods repeatedly.\n\nA trend can be useful; daily weighing is not required for everyone. If it becomes distressing, discuss another monitoring approach. Weight is one signal among several."],["Taking progress photos","Use similar lighting, camera distance, pose and clothing so comparisons are meaningful. Choose a private setting and only take or share images you are comfortable storing.\n\nAvoid manipulating posture or lighting to force a result. Photos cannot precisely measure body-fat percentage. Record the date and compare changes over a reasonable interval rather than searching for daily differences."],["Body measurements","Agree on the location and technique for each measurement. Use the same tape position and similar tension. A slightly different measurement point can create an apparent change that is only a method difference.\n\nKeep notes if the method changes. If a value seems surprising, repeat the measurement calmly before saving it. Do not keep only the reading you prefer."],["Strength tracking","Compare the same exercise, equipment, range, repetitions and effort. A heavier load with fewer repetitions or different technique does not tell the same story as a like-for-like improvement.\n\nRecord actual work, including changes in rest or setup. RIR and RPE add context to the load. Share patterns across several sessions with your coach."],["Body-composition changes","Body weight can stay similar while strength, measurements or appearance change. Consumer body-composition devices provide estimates that may be affected by conditions such as hydration.\n\nAvoid treating one percentage reading as a precise diagnosis. Use several consistent measures and consider how you feel and perform. Your coach can help interpret the pattern within the limits of the available data."],["Weekly check-ins","A useful check-in includes what happened and why: sessions completed, food practicality, hunger, sleep, wins and obstacles. Give the coach enough context to make an informed adjustment.\n\nMention relevant changes in work, travel, health or medication. Do not edit the story to appear compliant. The purpose is to improve the next week, not to receive a score for the last one."],["Beyond the scale","Progress can include better exercise technique, more comfortable daily movement, a repeatable meal routine or improved confidence in using the gym. Choose indicators that relate to your actual goal.\n\nKeep them concrete: “completed three planned sessions” is easier to review than “was healthier”. Your next action: select one outcome measure and two daily or weekly actions to discuss in your next check-in."]],"image":"assets/editorial/covers/progressive-overload.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"tracking","icon":"progress"},{"id":"hub-breathing","category":"Breathing & Performance","title":"Breathing & Performance","summary":"Use breathing cues to support controlled movement without turning them into rigid rules.","sections":[["Nasal breathing","Nasal breathing can be comfortable during rest and easier activity, but mouth breathing during hard exercise is a normal response to increased demand. Do not force one route if it makes the activity uncomfortable.\n\nUse breathing as an effort cue, not a test of toughness. Persistent or unusual breathing difficulty should be assessed by a qualified professional."],["Diaphragmatic breathing","Try quiet breathing in a comfortable seated or lying position. Let the lower ribs and abdomen move gently as you inhale, then exhale without forcing the air out. The goal is awareness, not the deepest possible breath.\n\nStop if you feel dizzy or uncomfortable. A brief practice may help you notice tension, but it is not a treatment for a medical breathing condition."],["Breathing during lifting","Coordinate breathing with the movement and the coach’s instructions. For many lighter exercises, exhaling through the demanding part and inhaling during the return is a useful starting cue.\n\nHeavy lifts can require different bracing strategies. Do not add prolonged breath-holding because you saw it online. Ask for individual instruction, especially if you have a condition affected by pressure changes."],["Bracing","Bracing means creating trunk tension to support the movement. It is not simply pulling the stomach inward. Your coach can help you find a repeatable setup for the load and exercise.\n\nPractise with an easy version before heavier work. A belt or a breathing cue does not replace learning the movement. Stop and reassess if the strategy produces pain or unusual symptoms."],["Breathing for cardio","Let breathing rise with effort. For an easier session, conversational breathing can help you stay near the intended intensity. Harder work will normally require a different pattern.\n\nAvoid treating a particular step-to-breath ratio as compulsory. Terrain, heat and fatigue change the demand. Follow the session purpose and slow down if the effort exceeds the plan."],["Recovery breathing","After a demanding effort, reduce activity gradually where appropriate and allow breathing to settle. A comfortable, unforced rhythm can be used during a short pause.\n\nDo not use hyperventilation or long breath holds as a routine recovery challenge. Your next action: ask your coach for one breathing and one bracing cue for the exercise you find hardest to control."]],"image":"assets/education/education-recovery.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"breathing","icon":"energy"},{"id":"hub-mobility","category":"Mobility & Injury Prevention","title":"Mobility & Injury Prevention","summary":"Prepare joints and movements sensibly, recognise problems early and know when coaching is not enough.","sections":[["Basic mobility","Mobility is the ability to use a range of movement with control. The useful range depends on the task and the person; more range is not always necessary.\n\nChoose movements that support your programme and practise them comfortably. Avoid forcing yourself into a position to match a photograph. Mobility work does not guarantee freedom from injury."],["Joint preparation","Use the warm-up to practise the positions and loads that the session requires. Begin with manageable movement and build toward working sets rather than jumping straight to the heaviest load.\n\nYour coach may use a specific preparation drill where it helps. The drill should have a clear reason. Longer preparation is not automatically better if it adds fatigue without improving readiness."],["Movement quality","A useful movement is controlled, repeatable and appropriate to the goal and current tolerance. Bodies do not all look identical in the same exercise.\n\nCheck the equipment setup, balance and the agreed range. Ask for a review if you are unsure what to change. A small adjustment to load or setup may be more useful than collecting many conflicting online cues."],["Common training mistakes","Frequent problems include increasing workload too quickly, rushing the setup, changing technique to finish a set and adding extra intensity methods without a plan.\n\nUse the prescribed progression and record what you actually did. Keep the training area clear and check equipment before loading it. If instructions are unclear, ask before starting rather than guessing under load."],["When to reduce training","Discuss reducing load, effort or volume when fatigue is accumulating, technique becomes unreliable or discomfort appears. A coach can adjust a programme but should not diagnose an injury from an app entry.\n\nDo not use painkillers or stimulants simply to push through a new problem. Describe the location, timing and circumstances of symptoms so you can be directed to suitable help."],["When to seek qualified healthcare","Seek professional assessment for persistent or worsening pain, significant swelling, loss of function or recurring symptoms. Urgent symptoms such as chest pain, fainting or sudden severe breathing difficulty require prompt medical help.\n\nThe app is a training and education tool, not a diagnostic service. Your next action: agree with your coach how to report a problem and what would mean stopping a session."]],"image":"assets/editorial/covers/hit-hiit.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"mobility","icon":"workouts"},{"id":"hub-real-life","category":"Real-Life Fitness","title":"Real-Life Fitness","summary":"Make training and food work during travel, busy periods, social events and Ramadan.","sections":[["Fitness while travelling","Plan around the trip you will actually have. Check the timetable, food access and realistic opportunities for movement. Travel days may need simpler expectations than ordinary days.\n\nKeep a few routines that help: regular meals where possible, comfortable movement and a plan for the first day back. Tell your coach the dates before leaving so the programme can be adjusted."],["Hotel workouts","Check what equipment the hotel has before assuming a full gym is available. Ask your coach for a short session using suitable bodyweight, dumbbell or machine exercises.\n\nUse safe, stable equipment and enough space. Do not improvise heavy resistance with furniture or unsuitable fixtures. A short session with familiar movements can be more useful than an elaborate unfamiliar circuit."],["Busy work schedules","Choose realistic training windows and protect the most achievable ones. A smaller plan completed consistently is often more useful than a large plan repeatedly postponed.\n\nPrepare a fallback meal and an equipment-light session. If meetings regularly displace workouts, change the schedule rather than relying on extra willpower. Use the weekly check-in to explain the actual constraint."],["Limited equipment","Keep the goal of the exercise in mind when choosing an alternative. Range, resistance, stability and effort all matter. A band and a machine may work the same general area without being equivalent in load.\n\nAsk for approved substitutions and record the variation used. Do not compare kilograms directly across different equipment. Progress can also mean improved control or more repetitions under the agreed conditions."],["Ramadan fitness basics","Discuss the fasting schedule, sleep, hydration opportunities and training timing with your coach before Ramadan. Sessions closer to a time when food and fluids are available may be more practical, depending on your routine.\n\nAvoid aggressive dieting, dehydration or demanding sessions that you cannot recover from. Medical conditions, pregnancy or medication require individual healthcare advice. The plan should respect both your observance and your health."],["Social events","Decide what you want from the event and make a few practical choices in advance. You can enjoy a meal and still return to your normal routine afterwards.\n\nDo not try to “earn” food with exercise or skip necessary meals beforehand. Tell your coach when celebrations are frequent so the plan reflects your actual life rather than an imaginary perfect week."],["Staying fit on vacation","Maintenance can be a worthwhile vacation goal. Walking, enjoyable activity and a simple meal pattern may be enough to keep continuity without scheduling the whole trip around training.\n\nAgree on your priorities before leaving and how to restart afterwards. Your next action: write a three-part travel plan—movement, meals and the first session back—and share it with your coach."]],"image":"assets/editorial/covers/checkin.webp","status":"published","version":1,"origin":"Panda Education 2026-09","language":"en","references":[],"hub":"real-life","icon":"target"}]$panda095$::jsonb) on conflict(kind,id) do nothing;
insert into public.panda_records(kind,id,data) select 'foods', value->>'id',value from jsonb_array_elements($panda095$[{"id":"ingredient_oats","name":"Rolled oats · dry","portion":100,"unit":"g","protein":13,"carbs":60,"fat":7,"fiber":10,"calories":355,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_yogurt","name":"Greek yogurt · plain, 0% fat","portion":100,"unit":"g","protein":10,"carbs":4,"fat":0.4,"fiber":0,"calories":59.6,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_milk","name":"Milk · 1.5% fat","portion":100,"unit":"g","protein":3.5,"carbs":5,"fat":1.5,"fiber":0,"calories":47.5,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_blueberry","name":"Blueberries · fresh","portion":100,"unit":"g","protein":0.7,"carbs":12,"fat":0.3,"fiber":2.4,"calories":53.5,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_chia","name":"Chia seeds","portion":100,"unit":"g","protein":17,"carbs":8,"fat":31,"fiber":34,"calories":379,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_banana","name":"Banana · peeled","portion":100,"unit":"g","protein":1.1,"carbs":20,"fat":0.3,"fiber":2.6,"calories":87.10000000000001,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_egg","name":"Whole egg · shell removed","portion":100,"unit":"g","protein":12.6,"carbs":0.7,"fat":9.5,"fiber":0,"calories":138.7,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_spinach","name":"Spinach · raw","portion":100,"unit":"g","protein":2.9,"carbs":1.4,"fat":0.4,"fiber":2.2,"calories":20.8,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_feta","name":"Feta cheese","portion":100,"unit":"g","protein":14,"carbs":4,"fat":21,"fiber":0,"calories":261,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_tomato","name":"Tomatoes · raw","portion":100,"unit":"g","protein":0.9,"carbs":2.7,"fat":0.2,"fiber":1.2,"calories":16.2,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_bread","name":"Wholegrain bread","portion":100,"unit":"g","protein":10,"carbs":40,"fat":4,"fiber":7,"calories":236,"category":"RECIPE INGREDIENTS","reviewed":false,"issue":"","notes":"Typical values; check the product and preparation state.","source":"Recipe ingredient reference","source_rows":[],"original":null},{"id":"ingredient_strawberry","name":"Strawberries · fresh","portion":100,"unit":"g","protein":0.7,"carbs":5.7,"fat":0.3,"fiber":2,"calories":28.3,"categor